<body>

  <div class="header">
    <h1>五 子 棋</h1>
    <div class="sub">双人对战 · 黑先白后</div>
  </div>

  <div class="board-wrap">
    <canvas id="board"></canvas>
  </div>

  <div class="info-panel">
    <div class="turn-box" id="turnBox">
      <span class="stone black" id="turnStone"></span>
      <span id="turnText">黑方落子</span>
    </div>
    <button class="btn" id="undoBtn">悔棋</button>
    <button class="btn" id="restartBtn">重新开始</button>
  </div>

  <div class="msg" id="msg"></div>

<script>
(function () {
  "use strict";

  // ============ 基础配置 ============
  const SIZE = 15;              // 15x15 棋盘
  const CELL = 40;              // 格子像素
  const PAD = 30;               // 边距
  const CANVAS = CELL * (SIZE - 1) + PAD * 2;

  const canvas = document.getElementById("board");
  const ctx = canvas.getContext("2d");
  canvas.width = CANVAS;
  canvas.height = CANVAS;

  // ============ 游戏状态 ============
  let board = [];               // board[r][c] = 0 | 1(黑) | 2(白)
  let current = 1;              // 1 黑, 2 白
  let history = [];             // 悔棋栈：{r, c}
  let gameOver = false;
  let winner = 0;

  // ============ 界面元素 ============
  const turnText = document.getElementById("turnText");
  const turnStone = document.getElementById("turnStone");
  const msg = document.getElementById("msg");
  const undoBtn = document.getElementById("undoBtn");
  const restartBtn = document.getElementById("restartBtn");

  // ============ 初始化 ============
  function init() {
    board = Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
    history = [];
    current = 1;
    gameOver = false;
    winner = 0;
    msg.textContent = "";
    updateTurnUI();
    draw();
  }

  // ============ 绘制棋盘 ============
  function draw() {
    // 背景
    ctx.fillStyle = "#e0b868";
    ctx.fillRect(0, 0, CANVAS, CANVAS);

    // 网格线
    ctx.strokeStyle = "#5a3d1a";
    ctx.lineWidth = 1;
    for (let i = 0; i < SIZE; i++) {
      const p = PAD + i * CELL;
      ctx.beginPath();
      ctx.moveTo(PAD, p);
      ctx.lineTo(PAD + CELL * (SIZE - 1), p);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(p, PAD);
      ctx.lineTo(p, PAD + CELL * (SIZE - 1));
      ctx.stroke();
    }

    // 星位（天元 + 四个星）
    const stars = [3, 7, 11];
    for (let r of stars) {
      for (let c of stars) {
        if ((r === 3 || r === 11) && (c === 3 || c === 11)) {
          drawStar(r, c);
        } else if (r === 7 && c === 7) {
          drawStar(r, c);
        }
      }
    }

    // 棋子（最后一步高亮）
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        if (board[r][c] !== 0) {
          drawStone(r, c, board[r][c], isLastMove(r, c));
        }
      }
    }
  }

  function drawStar(r, c) {
    ctx.fillStyle = "#5a3d1a";
    ctx.beginPath();
    ctx.arc(PAD + c * CELL, PAD + r * CELL, 4, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawStone(r, c, color, highlight) {
    const x = PAD + c * CELL;
    const y = PAD + r * CELL;
    const radius = CELL * 0.42;

    ctx.save();
    // 阴影
    ctx.shadowColor = "rgba(0,0,0,.5)";
    ctx.shadowBlur = highlight ? 12 : 5;
    ctx.shadowOffsetY = 2;

    const grad = ctx.createRadialGradient(
      x - radius * 0.35, y - radius * 0.35, radius * 0.15,
      x, y, radius
    );
    if (color === 1) {
      grad.addColorStop(0, "#6b6b6b");
      grad.addColorStop(0.6, "#222");
      grad.addColorStop(1, "#000");
    } else {
      grad.addColorStop(0, "#ffffff");
      grad.addColorStop(0.7, "#e8e8e8");
      grad.addColorStop(1, "#b8b8b8");
    }

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 最后一步标记
    if (highlight) {
      ctx.strokeStyle = color === 1 ? "#ffd75e" : "#e34";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(x, y, radius * 0.45, 0, Math.PI * 2);
      ctx.stroke();
    }
  }

  function isLastMove(r, c) {
    if (history.length === 0) return false;
    const last = history[history.length - 1];
    return last.r === r && last.c === c;
  }

  // ============ 落子 ============
  function canvasPos(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    const c = Math.round((x - PAD) / CELL);
    const r = Math.round((y - PAD) / CELL);
    return { r, c };
  }

  function handleClick(e) {
    if (gameOver) {
      msg.textContent = "本局已结束，请重新开始";
      return;
    }
    const { r, c } = canvasPos(e);
    if (r < 0 || r >= SIZE || c < 0 || c >= SIZE) return;
    if (board[r][c] !== 0) {
      msg.textContent = "此处已有棋子，请另选位置";
      return;
    }

    board[r][c] = current;
    history.push({ r, c });

    if (checkWin(r, c)) {
      winner = current;
      gameOver = true;
      msg.textContent = (winner === 1 ? "黑方" : "白方") + "获胜！🎉";
      updateTurnUI();
      draw();
      return;
    }

    if (history.length === SIZE * SIZE) {
      gameOver = true;
      msg.textContent = "平局！棋盘已满";
      updateTurnUI();
      draw();
      return;
    }

    current = current === 1 ? 2 : 1;
    msg.textContent = "";
    updateTurnUI();
    draw();
  }

  // ============ 胜负判定 ============
  function checkWin(r, c) {
    const color = board[r][c];
    const dirs = [
      [0, 1],   // 水平
      [1, 0],   // 垂直
      [1, 1],   // 主对角线
      [1, -1]   // 副对角线
    ];

    for (const [dr, dc] of dirs) {
      let count = 1;
      // 正方向
      for (let i = 1; i < 5; i++) {
        const nr = r + dr * i, nc = c + dc * i;
        if (nr < 0 || nr >= SIZE || nc < 0 || nc >= SIZE) break;
        if (board[nr][nc] === color) count++;
        else break;
      }
      // 反方向
      for (let i = 1; i < 5; i++) {
        const nr = r - dr * i, nc = c - dc * i;
        if (nr < 0 || nr >= SIZE || nc < 0 || nc >= SIZE) break;
        if (board[nr][nc] === color) count++;
        else break;
      }
      if (count >= 5) return true;
    }
    return false;
  }

  // ============ 悔棋 ============
  function undo() {
    if (history.length === 0) {
      msg.textContent = "还没有落子，无法悔棋";
      return;
    }
    if (gameOver) {
      // 胜负已定后允许悔棋（撤销制胜一手）
      const last = history.pop();
      board[last.r][last.c] = 0;
      current = winner;
      winner = 0;
      gameOver = false;
      msg.textContent = "已悔棋，请重新落子";
      updateTurnUI();
      draw();
      return;
    }
    const last = history.pop();
    board[last.r][last.c] = 0;
    current = current === 1 ? 2 : 1;
    msg.textContent = "";
    updateTurnUI();
    draw();
  }

  // ============ UI 更新 ============
  function updateTurnUI() {
    if (gameOver) {
      turnStone.className = "stone " + (winner === 1 ? "black" : "white");
      turnText.textContent = "对局结束";
      return;
    }
    turnStone.className = "stone " + (current === 1 ? "black" : "white");
    turnText.textContent = (current === 1 ? "黑方" : "白方") + "落子";
  }

  // ============ 事件绑定 ============
  canvas.addEventListener("click", handleClick);
  undoBtn.addEventListener("click", undo);
  restartBtn.addEventListener("click", init);

  // ============ 启动 ============
  init();
})();
</script>
</body>
</html>
